module betting_guarantee(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] julia_score,\n    input wire [31:0] other_scores_0,\n    input wire [31:0] other_scores_1,\n    input wire [31:0] other_scores_2,\n    input wire [31:0] other_scores_3,\n    input wire [31:0] other_scores_4,\n    input wire [31:0] other_scores_5,\n    input wire [31:0] other_scores_6,\n    input wire [31:0] other_scores_7,\n    input wire [2:0] valid_count,\n    output reg [31:0] guarantee_matches,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] PROC_S0     = 4'd1;\n    localparam [3:0] PROC_S1     = 4'd2;\n    localparam [3:0] PROC_S2     = 4'd3;\n    localparam [3:0] PROC_S3     = 4'd4;\n    localparam [3:0] PROC_S4     = 4'd5;\n    localparam [3:0] PROC_S5     = 4'd6;\n    localparam [3:0] PROC_S6     = 4'd7;\n    localparam [3:0] PROC_S7     = 4'd8;\n    localparam [3:0] CALCULATE   = 4'd9;\n    localparam [3:0] FINISH_ST   = 4'd10;\n\n    reg [3:0] state;\n    reg [31:0] max_score;\n    reg [31:0] second_max_score;\n    reg [31:0] count_max;\n    reg [7:0] cycle_counter;\n    reg [31:0] score_buffer [0:7];\n    reg processing;\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            max_score <= 32'd0;\n            second_max_score <= 32'd0;\n            count_max <= 32'd0;\n            cycle_counter <= 8'd0;\n            done <= 1'b0;\n            guarantee_matches <= 32'd0;\n            for (i = 0; i < 8; i = i + 1) score_buffer[i] <= 32'd0;\n            processing <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    guarantee_matches <= 32'd0;\n                    cycle_counter <= 8'd0;\n                    if (start) begin\n                        // Load scores into buffer\n                        score_buffer[0] <= other_scores_0;\n                        score_buffer[1] <= other_scores_1;\n                        score_buffer[2] <= other_scores_2;\n                        score_buffer[3] <= other_scores_3;\n                        score_buffer[4] <= other_scores_4;\n                        score_buffer[5] <= other_scores_5;\n                        score_buffer[6] <= other_scores_6;\n                        score_buffer[7] <= other_scores_7;\n\n                        // Initialize processing values\n                        max_score <= 32'd0;\n                        second_max_score <= 32'd0;\n                        count_max <= 32'd1;\n                        state <= PROC_S0;\n                        processing <= 1'b1;\n                    end\n                end\n\n                PROC_S0: begin\n                    if (valid_count > 0) begin\n                        max_score <= score_buffer[0];\n                        second_max_score <= 32'd0;\n                        count_max <= 32'd1;\n                    end\n                    state <= PROC_S1;\n                end\n\n                PROC_S1: begin\n                    if (valid_count > 1) begin\n                        if (score_buffer[1] > max_score) begin\n                            second_max_score <= max_score;\n                            max_score <= score_buffer[1];\n                            count_max <= 32'd1;\n                        end else if (score_buffer[1] == max_score) begin\n                            count_max <= count_max + 32'd1;\n                        end else if (score_buffer[1] > second_max_score) begin\n                            second_max_score <= score_buffer[1];\n                        end\n                    end\n                    state <= PROC_S2;\n                end\n\n                PROC_S2: begin\n                    if (valid_count > 2) begin\n                        if (score_buffer[2] > max_score) begin\n                            second_max_score <= max_score;\n                            max_score <= score_buffer[2];\n                            count_max <= 32'd1;\n                        end else if (score_buffer[2] == max_score) begin\n                            count_max <= count_max + 32'd1;\n                        end else if (score_buffer[2] > second_max_score) begin\n                            second_max_score <= score_buffer[2];\n                        end\n                    end\n                    state <= PROC_S3;\n                end\n\n                PROC_S3: begin\n                    if (valid_count > 3) begin\n                        if (score_buffer[3] > max_score) begin\n                            second_max_score <= max_score;\n                            max_score <= score_buffer[3];\n                            count_max <= 32'd1;\n                        end else if (score_buffer[3] == max_score) begin\n                            count_max <= count_max + 32'd1;\n                        end else if (score_buffer[3] > second_max_score) begin\n                            second_max_score <= score_buffer[3];\n                        end\n                    end\n                    state <= PROC_S4;\n                end\n\n                PROC_S4: begin\n                    if (valid_count > 4) begin\n                        if (score_buffer[4] > max_score) begin\n                            second_max_score <= max_score;\n                            max_score <= score_buffer[4];\n                            count_max <= 32'd1;\n                        end else if (score_buffer[4] == max_score) begin\n                            count_max <= count_max + 32'd1;\n                        end else if (score_buffer[4] > second_max_score) begin\n                            second_max_score <= score_buffer[4];\n                        end\n                    end\n                    state <= PROC_S5;\n                end\n\n                PROC_S5: begin\n                    if (valid_count > 5) begin\n                        if (score_buffer[5] > max_score) begin\n                            second_max_score <= max_score;\n                            max_score <= score_buffer[5];\n                            count_max <= 32'd1;\n                        end else if (score_buffer[5] == max_score) begin\n                            count_max <= count_max + 32'd1;\n                        end else if (score_buffer[5] > second_max_score) begin\n                            second_max_score <= score_buffer[5];\n                        end\n                    end\n                    state <= PROC_S6;\n                end\n\n                PROC_S6: begin\n                    if (valid_count > 6) begin\n                        if (score_buffer[6] > max_score) begin\n                            second_max_score <= max_score;\n                            max_score <= score_buffer[6];\n                            count_max <= 32'd1;\n                        end else if (score_buffer[6] == max_score) begin\n                            count_max <= count_max + 32'd1;\n                        end else if (score_buffer[6] > second_max_score) begin\n                            second_max_score <= score_buffer[6];\n                        end\n                    end\n                    state <= PROC_S7;\n                end\n\n                PROC_S7: begin\n                    if (valid_count > 7) begin\n                        if (score_buffer[7] > max_score) begin\n                            second_max_score <= max_score;\n                            max_score <= score_buffer[7];\n                            count_max <= 32'd1;\n                        end else if (score_buffer[7] == max_score) begin\n                            count_max <= count_max + 32'd1;\n                        end else if (score_buffer[7] > second_max_score) begin\n                            second_max_score <= score_buffer[7];\n                        end\n                    end\n                    state <= CALCULATE;\n                end\n\n                CALCULATE: begin\n                    if (max_score <= julia_score) begin\n                        if (max_score < julia_score) begin\n                            // Julia is uniquely highest\n                            guarantee_matches <= 32'd0;\n                        end else begin\n                            // Tie with highest group\n                            if (second_max_score > 0) begin\n                                guarantee_matches <= (julia_score - second_max_score) + 32'd1;\n                            end else begin\n                                guarantee_matches <= 32'd0;\n                            end\n                        end\n                    end else begin\n                        // Julia needs to pass others\n                        if (second_max_score > 0 && julia_score > second_max_score) begin\n                            guarantee_matches <= (max_score - julia_score) + (julia_score - second_max_score) + count_max;\n                        end else begin\n                            guarantee_matches <= (max_score - julia_score) + 32'd1;\n                        end\n                    end\n                    state <= FINISH_ST;\n                end\n\n                FINISH_ST: begin\n                    done <= 1'b1;\n                    processing <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule